using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "ShardsExtractorAction", menuName = "Data/Battle/Battle Actions/Tactical Actions/ShardsExtractorAction")]
public class ShardsExtractorAction : DiscardWithActionAction
{
	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		if (playerHand)
		{
			if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 1)
			{
				return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAtLeastTwoNonHexDice();
			}
			return false;
		}
		if (ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount() > 0)
		{
			return ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyPlayableNonHexActions();
		}
		return false;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return diceInstance.Dice.DiceTier != ReferenceSingleton<AssetsReference>.Instance.HexDieTier;
	}
}
